import{_ as t,o as a,c as i,aa as o}from"./chunks/framework.BAs_AphD.js";const n="/buildary-help-preview/media/en/tickets/en_pt_vykresy.png",r="/buildary-help-preview/media/en/tickets/en_nova_cast_stavby.png",f=JSON.parse('{"title":"Project Sections and Plans","description":"","frontmatter":{"title":"Project Sections and Plans","wiki":"en:tickets:project_structure"},"headers":[],"relativePath":"en/tickets/project_structure.md","filePath":"en/tickets/project_structure.md","lastUpdated":1794388980000}'),s={name:"en/tickets/project_structure.md"};function d(c,e,l,p,u,g){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="project-sections-and-plans" tabindex="-1">Project Sections and Plans <a class="header-anchor" href="#project-sections-and-plans" aria-label="Permalink to &quot;Project Sections and Plans&quot;">​</a></h1><figure class="shot" style="--w:520px;"><img src="'+n+'" alt="Project Parts and Drawings Code List" width="500" loading="lazy"></figure><p>This code list allows you to define the <strong>hierarchical structure</strong> of the project and, most importantly, <strong>upload drawings</strong>, which can then be used to add markers for more precise localization of individual tickets.</p><p>Use the <strong>+</strong> button to add another subordinate level under the currently selected part. At the first level, we recommend structuring the project according to its building objects. You can then divide the building objects into more detailed parts if needed.</p><p>A suitable project structure makes ticket localization significantly easier.</p><p>Each part has an icon showing the number of drawings it contains, if any.</p><figure class="shot" style="--w:600px;"><img src="'+r+'" alt="New Project Part and Drawings" width="580" loading="lazy"></figure><p>You can add one or more drawings to each part. You can add drawings to the project part window individually, drag and drop multiple drawings at once, or select multiple files and upload them. Drawings will be uploaded and sorted alphabetically by file name.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Drawings can be uploaded in PDF format or as an image (JPG, PNG, etc.).</p></div><p>Before uploading a drawing, you can rotate it to achieve the <strong>correct orientation</strong>. If you did not do this and the orientation is incorrect, you need to delete the drawing before its first use and upload it again with the correct rotation.</p><p>If you want a different drawing to be offered as the default drawing for a given part instead of the first drawing in alphabetical order, mark it as <strong>Default Drawing for This Project Part</strong> using the icon with a drawing and marker. The drawing will then be placed first regardless of its file name.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Uploading drawings is a time-consuming operation. The drawing is not only uploaded, but also divided into tiles so that subsequent work with it is fast. If you are uploading drawings to multiple parts, we recommend opening the application in multiple windows and uploading the drawings in parallel. This will significantly speed up the process.</p></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Drawings that have already been used in any records or tickets cannot be deleted. They can only be invalidated, so they will no longer be offered for future use.</p></div>',13)])])}const w=t(s,[["render",d]]);export{f as __pageData,w as default};
